mapper.select:
select s.settle_id, s.store_id, s.settle_no, s.settle_date, s.shift, s.order_count,
       s.total_amount, s.cash_amount, s.wechat_amount, s.alipay_amount, s.stored_amount,
       s.refund_amount, s.point_amount, s.diff_amount, s.diff_reason, s.status,
       s.settle_by, s.settle_time, s.create_by, s.create_time, s.update_by, s.update_time,
       s.remark
from biz_daily_settlement s


        and s.settle_no = #{settleNo}


        and s.shift = #{shift}


        and s.status = #{status}


        and s.settle_date >= #{params.beginTime}


        and s.settle_date <= #{params.endTime}


order by s.settle_id desc

mapper.update:
update biz_order
set settle_id = #{settleId}, update_time = now()
where store_id = #{storeId}
  and status <> 5
  and settle_id = 0
  and create_time >= #{begin}
  and create_time <= #{end}
